<nav class="step-indicator mb-4" aria-label="Application steps">
    <ol class="d-flex list-unstyled justify-content-between position-relative px-0">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var stepIndex = i;
            var state = GetStepState(stepIndex);
            <li class="step-item text-center flex-fill @state" @key="stepIndex">
                @if (state == "completed")
                {
                    <button type="button" class="step-circle btn btn-success rounded-circle" @onclick="() => GoToStep(stepIndex)">
                        <span>&#10003;</span>
                    </button>
                }
                else
                {
                    <span class="step-circle @(state == "active" ? "bg-primary text-white" : "bg-secondary text-white") rounded-circle d-inline-flex align-items-center justify-content-center">
                        @(stepIndex + 1)
                    </span>
                }
                <div class="step-label mt-1 small @(state == "dimmed" ? "text-muted" : "")">@StepNames[stepIndex]</div>
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnStepSelected { get; set; }

    private static readonly string[] StepNames =
    [
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    ];

    private string GetStepState(int step)
    {
        if (step == CurrentStep) return "active";
        if (step < CurrentStep) return "completed";
        return "dimmed";
    }

    private async Task GoToStep(int step)
    {
        if (step < CurrentStep)
            await OnStepSelected.InvokeAsync(step);
    }
}
