+        <p class="mb-0">Your application has been received. Your application ID is <strong>@ApplicationId</strong>.</p>
+    </div>
+}
+else
+{
+    <!-- Personal Info -->
+    <div class="card mb-3">
+        <div class="card-header d-flex justify-content-between align-items-center">
+            <strong>Personal Information</strong>
+            <button type="button" class="btn btn-link btn-sm p-0" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
+        </div>
+        <div class="card-body">
+            <dl class="row mb-0">
+                <dt class="col-sm-3">Full Name</dt><dd class="col-sm-9">@FullName</dd>
+                <dt class="col-sm-3">Email</dt><dd class="col-sm-9">@Email</dd>
+                <dt class="col-sm-3">Phone</dt><dd class="col-sm-9">@Phone</dd>
+                <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@Address</dd>
+            </dl>
+        </div>
+    </div>
+
+    <!-- Work History -->
+    <div class="card mb-3">
+        <div class="card-header d-flex justify-content-between align-items-center">
+            <strong>Work History</strong>
+            <button type="button" class="btn btn-link btn-sm p-0" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
+        </div>
+        <div class="card-body">
+            @foreach (var entry in WorkEntries)
+            {
+                <div class="mb-3 pb-2 border-bottom">
+                    <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
+                    <span class="text-muted">
+                        @entry.StartDate.ToString("MMM yyyy") &ndash;
+                        @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
+                    </span>
+                    @if (!string.IsNullOrWhiteSpace(entry.Description))
+                    {
+                        <p class="mt-1 mb-0">@entry.Description</p>
+                    }
+                </div>
+            }
+        </div>
+    </div>
+
+    <!-- References -->
+    <div class="card mb-3">
+        <div class="card-header d-flex justify-content-between align-items-center">
+            <strong>References</strong>
+            <button type="button" class="btn btn-link btn-sm p-0" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
+        </div>
+        <div class="card-body">
+            @foreach (var r in References)
+            {
+                <div class="mb-2">
+                    <strong>@r.Name</strong> (@r.Relationship)<br />
+                    <span class="text-muted">@r.Email &middot; @r.Phone</span>
+                </div>
+            }
+        </div>
+    </div>
+
+    <!-- Cover Letter -->
+    <div class="card mb-3">
+        <div class="card-header d-flex justify-content-between align-items-center">
+            <strong>Cover Letter</strong>
+            <button type="button" class="btn btn-link btn-sm p-0" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
+        </div>
+        <div class="card-body">
+            <p style="white-space: pre-wrap;" class="mb-0">@CoverLetter</p>
+        </div>
+    </div>
+
+    @if (SubmissionError is not null)
+    {
+        <div class="alert alert-danger">@SubmissionError</div>
+    }
+
+    <div class="d-flex justify-content-between">
+        <button class="btn btn-secondary" @onclick="OnBack">Back</button>
+        <button class="btn btn-success" @onclick="HandleSubmit" disabled="@IsSubmitting">
+            @if (IsSubmitting)
+            {
+                <span class="spinner-border spinner-border-sm me-1" role="status"></span>
+            }
+            Submit Application
+        </button>
+    </div>
+}
+
+@code {
+    [Parameter] public string FullName { get; set; } = "";
+    [Parameter] public string Email { get; set; } = "";
+    [Parameter] public string Phone { get; set; } = "";
+    [Parameter] public string Address { get; set; } = "";
+    [Parameter] public List<WorkHistoryStep.WorkEntryModel> WorkEntries { get; set; } = new();
+    [Parameter] public List<ReferencesStep.ReferenceModel> References { get; set; } = new();
+    [Parameter] public string CoverLetter { get; set; } = "";
+    [Parameter] public EventCallback<int> OnEditStep { get; set; }
+    [Parameter] public EventCallback OnBack { get; set; }
+    [Parameter] public Func<Task<int>>? OnSubmit { get; set; }
+
+    private bool IsSubmitting;
+    private bool IsSubmitted;
+    private int ApplicationId;
+    private string? SubmissionError;
+
+    private async Task HandleSubmit()
+    {
+        if (OnSubmit is null) return;
+
+        IsSubmitting = true;
+        SubmissionError = null;
+        StateHasChanged();
+
+        try
+        {
+            ApplicationId = await OnSubmit();
+            IsSubmitted = true;
+        }
+        catch (Exception ex)
+        {
+            SubmissionError = $"Submission failed: {ex.Message}. Please try again.";
+        }
+        finally
+        {
+            IsSubmitting = false;
+        }
+    }
+}
+

