@page "/apply"
@using sv_99410250cbd548b4828f61297bb868e1.Components.Pages.Apply
@using sv_99410250cbd548b4828f61297bb868e1.Services
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4 text-center">Job Application</h2>

    <StepIndicator CurrentStep="currentStep" OnStepSelected="GoToStep" />

    <div class="mt-4">
        @switch (currentStep)
        {
            case 0:
                <PersonalInfoStep
                    @bind-FullName="fullName"
                    @bind-Email="email"
                    @bind-Phone="phone"
                    @bind-Address="address"
                    ValidateEmail="ApplicationService.ValidateEmailAsync"
                    OnNext="NextStep" />
                break;

            case 1:
                <WorkHistoryStep
                    @bind-Entries="workEntries"
                    OnNext="NextStep"
                    OnBack="PreviousStep" />
                break;

            case 2:
                <ReferencesStep
                    @bind-References="references"
                    OnNext="NextStep"
                    OnBack="PreviousStep" />
                break;

            case 3:
                <CoverLetterStep
                    @bind-CoverLetter="coverLetter"
                    OnNext="NextStep"
                    OnBack="PreviousStep" />
                break;

            case 4:
                <ReviewStep
                    FullName="@fullName"
                    Email="@email"
                    Phone="@phone"
                    Address="@address"
                    WorkEntries="workEntries"
                    References="references"
                    CoverLetter="@coverLetter"
                    OnEditStep="GoToStep"
                    OnBack="PreviousStep"
                    OnSubmit="SubmitApplication" />
                break;
        }
    </div>
</div>

@code {
    private int currentStep;

    // Step 1 state
    private string fullName = "";
    private string email = "";
    private string phone = "";
    private string address = "";

    // Step 2 state
    private List<WorkHistoryStep.WorkEntryModel> workEntries = [new()];

    // Step 3 state
    private List<ReferencesStep.ReferenceModel> references = [new(), new()];

    // Step 4 state
    private string coverLetter = "";

    private void NextStep() => currentStep = Math.Min(currentStep + 1, 4);
    private void PreviousStep() => currentStep = Math.Max(currentStep - 1, 0);
    private void GoToStep(int step) => currentStep = step;

    private async Task<int> SubmitApplication()
    {
        var personalInfo = new PersonalInfo(fullName, email, phone, address);

        var workHistory = new WorkHistory(workEntries.Select(e =>
            new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)
        ).ToList());

        var refs = references.Select(r =>
            new Reference(r.Name, r.Relationship, r.Email, r.Phone)
        ).ToList();

        var application = new JobApplication(personalInfo, workHistory, refs, coverLetter);
        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

.step-circle {
    width: 36px;
    height: 36px;
    font-size: 0.85rem;
    font-weight: 600;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border: none;
}

::deep .step-item.completed .step-circle {
    cursor: pointer;
}

::deep .step-item.dimmed .step-circle {
    opacity: 0.5;
}

